import type { Metadata } from "next";
import { getSiteUrl, siteConfig } from "@/config/site";
import { getDictionary } from "@/i18n";
import { DEFAULT_LOCALE, LOCALE_META, LOCALES, type Locale } from "@/i18n/config";
import { href, type RouteKey } from "@/i18n/routes";

/** Generated by scripts/build-brand-assets.mjs. */
export const OG_IMAGE = {
  url: "/brand/og-image.png",
  width: 1200,
  height: 630,
  alt: "AMIR – Digital · AI · Automation",
};

interface BuildMetadataInput {
  /** Page title; the layout template appends the brand. `null` uses the default title. */
  title: string | null;
  description: string;
  route: RouteKey;
  slug?: string;
  locale?: Locale;
  noIndex?: boolean;
}

/** Bing Webmaster Tools ownership token (public by design; keep the tag so the site stays verified). */
const BING_SITE_VERIFICATION = "7249AD4E1397ECD7FC1AEC4234692A31";

export function absoluteUrl(path: string): string {
  return path === "/" ? getSiteUrl() : `${getSiteUrl()}${path}`;
}

export function buildMetadata({
  title,
  description,
  route,
  slug,
  locale = DEFAULT_LOCALE,
  noIndex = false,
}: BuildMetadataInput): Metadata {
  const t = getDictionary(locale);
  const canonical = absoluteUrl(href(route, { slug, locale }));
  const languages: Record<string, string> = Object.fromEntries(
    LOCALES.map((l) => [l, absoluteUrl(href(route, { slug, locale: l }))]),
  );
  languages["x-default"] = absoluteUrl(href(route, { slug, locale: DEFAULT_LOCALE }));
  const fullTitle = title ? `${title} | ${t.meta.titleSuffix}` : t.meta.defaultTitle;

  return {
    title: title ?? { absolute: t.meta.defaultTitle },
    description,
    alternates: { canonical, languages },
    openGraph: {
      title: fullTitle,
      description,
      url: canonical,
      siteName: siteConfig.name,
      locale: LOCALE_META[locale].ogLocale,
      alternateLocale: LOCALES.filter((l) => l !== locale).map((l) => LOCALE_META[l].ogLocale),
      type: "website",
      images: [
        { url: OG_IMAGE.url, width: OG_IMAGE.width, height: OG_IMAGE.height, alt: OG_IMAGE.alt },
      ],
    },
    twitter: { card: "summary_large_image", title: fullTitle, description, images: [OG_IMAGE.url] },
    verification: { other: { "msvalidate.01": BING_SITE_VERIFICATION } },
    ...(noIndex ? { robots: { index: false, follow: true } } : {}),
  };
}
